{
  "a_sentences": [
    {
      "a_text": "Der Streit dreht sich um den Anspruch der Versicherten auf eine Hilflosenentschädigung schweren Grades sowie um den Beginn dieses Anspruchs vor dem 1. April 2023.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Die Versicherte war von Dezember 2023 bis Ende April 2024 über eine naso-gastrale Sonde ernährt; da diese Hilfe weniger als ein Jahr dauerte, begründet dies keinen regelmässigen und erheblichen Hilfsbedarf beim Essen.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Die Notwendigkeit, die Mahlzeiten zum Sitzen zu bringen, fällt unter die bereits anerkannten Hilfsbedarfe bei den Akten «sich aufstehen, sich setzen, sich hinlegen» und «sich fortbewegen», nicht unter den Akt «essen».",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Eine Hilflosenentschädigung schweren Grades setzt voraus, dass die versicherte Person für alle sechs alltäglichen Lebensverrichtungen regelmässig und erheblich fremde Hilfe benötigt und zudem dauernde Pflege oder persönliche Überwachung braucht; diese Voraussetzungen sind hier nicht erfüllt.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Gemäss Art. 46 Abs. 2 AHVG wird die Hilflosenentschädigung bei verspäteter Geltendmachung nur für die zwölf Monate vor der Antragstellung ausgerichtet.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Eine bloss gelegentliche Hilfe beim Zerkleinern harter Speisen oder die Notwendigkeit, zum Essen begleitet zu werden, genügt nicht für einen regelmässigen und erheblichen Hilfsbedarf beim Essen.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Das Bundesgericht bestätigt die vorinstanzliche Beurteilung, dass kein regelmässiger und erheblicher Hilfsbedarf beim Essen besteht, weshalb eine Hilflosenentschädigung schweren Grades nicht gewährt werden kann.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Da die Versicherte ihren Anspruch erst nach Ablauf der zwölfmonatigen Karenzfrist geltend gemacht hat, wird die Hilflosenentschädigung mittleren Grades erst ab dem 1. April 2023 ausgerichtet.",
      "b_propositions": ["P8"]
    }
  ]
}
